INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch09$PT156-S2-Q12$batch09$, 156, 2, 12, $batch09$Principle-Strengthen$batch09$, $batch09$Politician: Tightening air quality standards that regulate industrial emissions would cause industries to move to locations with less stringent standards concerning these emissions. So current standards, which are already quite stringent, should not be raised, since there is not enough evidence that the decreased pollution that would admittedly result from raising the standards would compensate for the loss of jobs caused by the relocation of key industries.$batch09$, $batch09$Which one of the following principles, if valid, most helps to justify the politician’s reasoning?$batch09$, $batch09$C$batch09$, true, $batch09$Batch 09; question text from local bank.$batch09$ FROM lr_sections s WHERE s.preptest=156 AND s.section=2 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch09$PT156-S2-Q12$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$A$batch09$, $batch09$Governmental policy should generally be designed to encourage the growth of key industries.$batch09$, $batch09$Not the Reasoning$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT156-S2-Q12$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$A$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$B$batch09$, $batch09$The extent to which the people are willing to accept a governmental policy should be the only factor determining whether that policy is adopted.$batch09$, $batch09$Out of Scope$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT156-S2-Q12$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$B$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$C$batch09$, $batch09$Governmental policy should be altered only if there is compelling evidence that the consequences of doing so are better than the consequences of not doing so.$batch09$, $batch09$Correct$batch09$, true FROM lr_questions q WHERE q.qid=$batch09$PT156-S2-Q12$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$C$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$D$batch09$, $batch09$Governmental policy should be changed in those cases in which retaining the policy and changing it each have positive and negative consequences.$batch09$, $batch09$Opposite$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT156-S2-Q12$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$D$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$E$batch09$, $batch09$If one lacks clear evidence about whether a given action will have a specified consequence, then one should assume that it will have that consequence when deciding whether to perform that action.$batch09$, $batch09$Opposite$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT156-S2-Q12$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$E$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch09$PT156-S2-Q12$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch09$Conclusion$batch09$, $batch09$The current air quality standards, already quite stringent, should not be raised.$batch09$), (1, $batch09$Evidence$batch09$, $batch09$Tighter standards would drive industries to places with looser rules. There isn't enough evidence that the reduced pollution would make up for the lost jobs.$batch09$), (2, $batch09$Evaluate$batch09$, $batch09$The politician admits raising the standards would reduce pollution. The argument isn't "raising them is bad." It's "we don't have enough evidence that raising them is better." So the principle has to say a policy shouldn't change without good evidence that the change is better.$batch09$), (3, $batch09$Goal$batch09$, $batch09$Don't change a policy unless there's strong evidence the change leads to better results.$batch09$)) v(position,label,body) WHERE q.qid=$batch09$PT156-S2-Q12$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch09$A$batch09$, $batch09$Protecting key industries leans the politician's way. But the argument turns on missing evidence about whether the change is worth it. A ignores that and never weighs the pollution benefit the politician admits.$batch09$), ($batch09$B$batch09$, $batch09$Public acceptance never comes up.$batch09$), ($batch09$C$batch09$, $batch09$"Altered only if" puts compelling evidence on the right: change → compelling evidence. Contrapose it: no compelling evidence → don't change. The politician says the evidence isn't there, so the standards shouldn't be raised.$batch09$), ($batch09$D$batch09$, $batch09$Both options here have upsides and downsides: cleaner air on one side, jobs on the other. D says that's when policy should be changed, which is the reverse of the conclusion.$batch09$), ($batch09$E$batch09$, $batch09$The politician lacks clear evidence that the benefits would make up for the losses. E says to assume they would, which supports raising the standards.$batch09$)) v(letter,body) WHERE q.qid=$batch09$PT156-S2-Q12$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
